// FINAL CANDIDATE — in-memory rendering overrides, no product or personal data adapter.
// User review narrowed scope: retain Task list rail/month review markers, improve checkboxes,
// mixed-precision Daily Record planning, slash completion and the Evening entry.
const oldBind=bind,oldAction=action,oldCollaboration=collaboration;
variants.F=['最终候选','保留现有页面结构 · 等待过目'];variant='F';showContext=false;
baseline.splice(0,baseline.length,
 {id:'p1',band:'上午',start:480,end:600,name:'规划与整理',note:'先规划，再整理今天需要处理的资料。'},
 {id:'p4',band:'上午',start:660,end:720,name:'阅读与学习',note:'已有明确起止时间的计划。'},
 {id:'p2',band:'午后',start:null,end:null,name:'整理本周安排',note:'午后择一段时间，先盘点再决定下一步。'},
 {id:'p3',band:'晚间',start:1110,end:1170,name:'晚饭与休息',note:'留出吃饭、休息与转换的时间。'});
plans=structuredClone(baseline);
let selectedDay=10,finalDrag=null,finalResize=null,finalAutoScroll=null,finalScrollFrame=null;
const planLabel=p=>p.start==null?`${p.band} · 具体时间未定`:`${time(p.start)}–${time(p.end)}`;
const reviewedDays=new Set([1,2,3,4,5,6,7]),recordedDays=new Set([8,9,10]);
const dayStatus=n=>reviewedDays.has(n)?'reviewed':recordedDays.has(n)?'unreviewed':'missing';
const selectedDate=()=>`2026-10-${String(selectedDay).padStart(2,'0')}`;
function finalRow(t){return `<article class="final-task-row"><div class="final-task-body"><button class="final-task-title ${t.done?'done':''}" data-task="${t.id}">${esc(t.name)}</button> <span class="pill">${t.done?'已完成':'待办'}</span><p>${esc(t.note||'尚未补充内容。')}</p><span class="tiny muted">${t.list} · ${t.date||'未排期'}${t.time!=null?' · '+time(t.time):''}</span></div><div class="final-task-actions"><button class="text-button" data-task="${t.id}">详情</button><button class="text-button" data-discuss="${t.id}">与 Codex 讨论</button><label class="final-complete"><input type="checkbox" data-complete="${t.id}" aria-label="${t.done?'重新打开':'完成'} ${esc(t.name)}" ${t.done?'checked':''}>${t.done?'重新打开':'完成'}</label><button class="text-button" data-task-more="${t.id}">更多 ···</button></div></article>`}
function pendingRows(list){const pending=list.filter(t=>!t.done),done=list.filter(t=>t.done);return pending.map(finalRow).join('')+(pending.length?'':'<p class="muted">这个范围没有待办。</p>')+(done.length?`<details class="final-task-history"><summary>已完成与已放弃 · ${done.length}</summary>${done.map(finalRow).join('')}</details>`:'')}
function tickMarkup(){return Array.from({length:15},(_,i)=>`<span class="time-tick" style="top:${i*72}px">${String(i+8).padStart(2,'0')}:00</span>`).join('')}
function planPositions(){const positions=new Map(),ordered=plans.filter(p=>p.start!=null).sort((a,b)=>a.start-b.start);let group=[],until=-1;const flush=()=>{const ends=[];for(const p of group){let lane=ends.findIndex(end=>end<=p.start);if(lane<0)lane=ends.length;ends[lane]=p.end;positions.set(p.id,{lane})}for(const p of group)positions.get(p.id).count=ends.length;group=[]};for(const p of ordered){if(p.start>=until){flush();until=-1}group.push(p);until=Math.max(until,p.end)}flush();return positions}
const oldEvening=evening;evening=()=>{let html=oldEvening();for(const p of plans)html=html.replace(`<li>${p.band} · ${esc(p.name)}</li>`,`<li>${planLabel(p)} · ${esc(p.name)}</li>`);return html};
timeline=()=>{const positions=planPositions();return `<div class="timeline-head"><span></span><b>当前计划</b><b>Task 与已记录事实</b></div><div class="timeline-scroll"><div class="timeline" data-timeline tabindex="0" aria-label="当前计划和 Task 时间轴；可拖动、调整计划结束时间和选区新建">${tickMarkup()}<div class="divider"></div>${plans.filter(p=>p.start!=null).map(p=>`<button class="exact-plan ${positions.get(p.id).count>1?'overlap-plan':''}" draggable="true" data-plan="${p.id}" style="left:${1+positions.get(p.id).lane*47/positions.get(p.id).count}%;width:${47/positions.get(p.id).count-.5}%;top:${(p.start-480)*1.2}px;height:${(p.end-p.start)*1.2}px"><span class="plan-range">${planLabel(p)}</span><strong>${esc(p.name)}</strong><span class="tiny">${esc(p.note)}</span><span class="plan-resize" data-resize-plan="${p.id}" draggable="false" title="拖动底边调整结束时间"></span></button>`).join('')}${tasks.filter(t=>t.date==='2026-10-10'&&t.time!=null&&!t.done).map(t=>`<button class="timed-task" draggable="true" data-task="${t.id}" data-drag-task="${t.id}" style="top:${(t.time-480)*1.2}px;height:${t.duration*1.2}px"><div><span>${time(t.time)} · Task</span><b>${esc(t.name)}</b></div></button>`).join('')}${facts.filter(f=>f.time!=null).map(f=>`<div class="actual-fact" style="top:${(f.time-480)*1.2}px;height:48px"><span class="pill fact">已记录</span> ${time(f.time)}<br>${esc(f.name)}</div>`).join('')}<div class="now-line"><span>14:15</span></div><div class="selection-ghost hidden"></div><div class="drop-feedback" hidden><span></span></div></div></div>`};
today=()=>{let content='';if(phase==='evening')return header('今天','2026 年 10 月 10 日 · 周六')+phaseTabs()+evening();if(phase==='morning')content=`<section class="surface"><div class="section-title"><h2>早间计划</h2><span class="pill">独立保留的基准</span></div>${baseline.map(p=>`<div class="agenda-band"><div style="font-weight:600;color:#79643a">${planLabel(p)}</div><div><b>${esc(p.name)}</b><p class="muted content-copy">${esc(p.note)}</p></div></div>`).join('')}<p class="help-note">早间计划可以同时有具体时间和宽泛时段。白天调整的是当前计划，这里保留原始安排。</p></section>`;
else content=`<div class="final-day-layout"><section class="surface final-timeline"><div class="section-title"><h2>时间安排与记录</h2><span class="tiny muted">计划 · Task · 事实</span></div>${plans.filter(p=>p.start==null).map(p=>`<div class="planning-strip" draggable="true" data-unscheduled-plan="${p.id}"><div><b>${p.band} · ${esc(p.name)}</b><p>具体时间未定。可拖入左侧时间轴，或直接设定时间。</p></div><button class="btn" data-edit-plan="${p.id}">设定时间</button></div>`).join('')}<div class="final-help"><span>拖动改时间；计划底边可调整结束时间。</span><details><summary>更多操作</summary><p>右侧空白选区新建 Task。拖到时间轴上下边缘会自动滚动；也可点击计划直接输入起止时间。</p></details></div>${timeline()}<details class="help-note"><summary>04:00–08:00 与 22:00–次日04:00</summary><p>示例没有这些时段的安排；正式 lived day 仍从 04:00 到次日 04:00。</p></details></section>${taskSummary()}</div>`;return header('今天','2026 年 10 月 10 日 · 周六',btn('晚间复盘','evening')+btn('与 Codex 讨论','collaboration','primary'))+phaseTabs()+content};
taskPage=()=>{const list=filteredTasks();const labels=[['all','全部'],['today','今天'],['inbox','Inbox'],['later','以后想做'],['archived','已归档']];return header('任务','保留清单结构；任务在今天与日历中使用同一份记录',btn('新任务','new-task','primary'))+`<section class="surface final-list-layout"><aside class="final-lists"><h2>清单</h2><div class="list-scope">${labels.map(([key,label])=>`<button class="btn ${scope===key?'active':''}" data-scope="${key}"><span>${label}</span><span class="muted">${tasks.filter(t=>!t.done&&(key==='all'||key==='today'&&t.date==='2026-10-10'||key==='inbox'&&t.list==='Inbox'||key==='later'&&t.list==='以后想做')).length}</span></button>`).join('')}</div><p class="help-note">清单用于组织任务。</p></aside><div><div class="section-title"><h2>${labels.find(([key])=>key===scope)?.[1]||'全部任务'}</h2><span class="muted tiny">${list.filter(t=>!t.done).length} 待办</span></div>${quickAdd()}${pendingRows(list)}</div></section>`};
function finalMonth(){const dayTasks=n=>tasks.filter(t=>t.date===`2026-10-${String(n).padStart(2,'0')}`);return `<div class="week-head">${['日','一','二','三','四','五','六'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:42},(_,i)=>{const n=i-3,inMonth=n>0&&n<=31,number=n<1?n+30:n>31?n-31:n,status=inMonth?dayStatus(n):'missing',items=inMonth?dayTasks(n):[],statusLabel=status==='reviewed'?'已有晚间复盘':status==='unreviewed'?'有记录，尚未晚间复盘':'没有记录';return `<button class="calendar-day ${n===10?'today':''}" ${inMonth?`data-final-day="${n}"`:'disabled'} aria-pressed="${n===selectedDay}" aria-label="${inMonth?'10':'相邻月份'} 月 ${number} 日 · ${statusLabel}${items.length?' · '+items.length+' 个 Task':''}"><span class="calendar-day-top"><strong class="day-number ${inMonth?'':'muted'}">${number}</strong>${n===10?'<small class="tiny">今天</small>':''}</span>${items.slice(0,calendarLines).map(t=>`<span class="calendar-task ${t.done?'done':''}" title="${esc(t.name)}">${esc(t.name)}</span>`).join('')}${items.length>calendarLines?`<span class="calendar-more">＋ ${items.length-calendarLines} 项</span>`:''}<span class="calendar-day-marker ${status}" aria-hidden="true">${status==='reviewed'?'复':status==='unreviewed'?'记':''}</span></button>`}).join('')}</div>`}
calendarPage=()=>{const status=dayStatus(selectedDay),items=tasks.filter(t=>t.date===selectedDate());return header('日历','2026 年 10 月 · 选择日期，查看原有记录和 Task',btn(calendarLines===4?'两行预览':'四行预览','calendar-lines'))+`<section class="final-calendar"><div class="calendar-layout"><section class="surface"><div class="section-title"><h2>2026 年 10 月</h2></div><div class="calendar-legend"><span><i class="legend-dot"></i>已有晚间复盘</span><span><i class="legend-dot unreviewed"></i>有记录，尚未复盘</span><span>空白：没有记录</span></div>${finalMonth()}</section><aside class="surface final-record-preview day-preview"><span class="pill">所选日期</span><h2>10 月 ${selectedDay} 日</h2><p class="preview-state ${status}">${status==='reviewed'?'已有晚间复盘':status==='unreviewed'?'尚无晚间复盘':'尚无 Daily Record'}</p>${selectedDay===10?`<h3>当前计划</h3>${plans.map(p=>`<p><b>${planLabel(p)}</b><br>${esc(p.name)}</p>`).join('')}<h3>已记录</h3><p>阅读了 25 分钟；桌面整理完成。</p>`:status==='reviewed'?'<p>这个示例日期已有晚间复盘，点击打开对应日期。</p>':'<p>没有补造该日期的活动或复盘。</p>'}<button class="btn" data-open-final-day="${selectedDay}">打开当天</button></aside></div><section class="surface final-calendar-task-section"><div class="section-title"><h2>10 月 ${selectedDay} 日的 Task</h2><span class="tiny muted">${items.length} 项</span></div>${pendingRows(items)}<button class="btn" data-new-selected="true">添加这个日期的 Task</button></section></section>`};
collaboration=()=>{const saved=variant;variant='B';const html=oldCollaboration();variant=saved;return html};
render=()=>{updateUrl();$('.app-shell').dataset.workspaceDestination=page;document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));$('#page').innerHTML=page==='today'?today():page==='tasks'?taskPage():page==='calendar'?calendarPage():collaboration();$('#variant-name').textContent='最终候选 · 待你过目';$('#variant-description').textContent=`${pages[page]} · ${lastAction==='等待操作'?'仅内存示例':lastAction}`;bind();if(page==='collaboration')updateCommandMenu()};
cycle=()=>{};
function openPlanEditor(p,start=p.start,end=p.end){const d=$('#detail-dialog');d.innerHTML=`<h2>调整当前计划</h2><p><b>${esc(p.name)}</b></p><form id="plan-editor"><label>时间精度</label><select id="plan-precision"><option value="exact" ${start!=null?'selected':''}>具体起止时间</option><option value="broad" ${start==null?'selected':''}>宽泛时段</option></select><div class="plan-edit-grid" id="plan-time-fields" ${start==null?'hidden':''}><div><label for="plan-start">开始</label><input id="plan-start" type="time" value="${time(start??840)}"></div><div><label for="plan-end">结束</label><input id="plan-end" type="time" value="${time(end??900)}"></div></div><div id="plan-band-field" ${start!=null?'hidden':''}><label>时段</label><select id="plan-band">${['上午','午后','晚间'].map(b=>`<option ${p.band===b?'selected':''}>${b}</option>`).join('')}</select></div><p class="plan-edit-note">调整后更新当前计划；早间基准和已记录事实保留。</p><div class="inline-actions"><button class="btn" type="button" id="cancel-plan">取消</button><button class="btn primary">采用这个安排</button></div></form>`;d.showModal();$('#cancel-plan').onclick=()=>d.close();$('#plan-precision').onchange=e=>{$('#plan-time-fields').hidden=e.target.value!=='exact';$('#plan-band-field').hidden=e.target.value==='exact'};$('#plan-editor').onsubmit=e=>{e.preventDefault();if($('#plan-precision').value==='exact'){const minute=v=>v?+v.slice(0,2)*60+(+v.slice(3)):null,a=minute($('#plan-start').value),b=minute($('#plan-end').value);if(a==null||b==null||b<=a){notify('请选择有效的开始和结束时间');return}if(a<480||b>1320){notify('此原型的可操作示例窗口为 08:00–22:00');return}p.start=a;p.end=b;p.band=bandOf(a)}else{p.start=null;p.end=null;p.band=$('#plan-band').value}d.close();render();notify(`当前计划更新：${p.name} · ${planLabel(p)}`)}}
function stopScroll(){finalAutoScroll=null;if(finalScrollFrame){cancelAnimationFrame(finalScrollFrame);finalScrollFrame=null}}
function autoScroll(scroller,clientY){const r=scroller.getBoundingClientRect();const direction=clientY<r.top+36?-1:clientY>r.bottom-36?1:0;if(!direction){stopScroll();return}finalAutoScroll={scroller,direction};if(!finalScrollFrame){const frame=()=>{if(!finalAutoScroll){finalScrollFrame=null;return}finalAutoScroll.scroller.scrollTop+=finalAutoScroll.direction*9;finalScrollFrame=requestAnimationFrame(frame)};finalScrollFrame=requestAnimationFrame(frame)}}
bindTimeline=()=>{document.querySelectorAll('[data-drag-task],[data-plan],[data-unscheduled-plan]').forEach(el=>{el.ondragstart=e=>{if(e.target.closest('[data-resize-plan]')){e.preventDefault();return}const kind=el.dataset.dragTask?'task':el.dataset.unscheduledPlan?'broad-plan':'plan',id=el.dataset.dragTask||el.dataset.unscheduledPlan||el.dataset.plan;finalDrag={kind,id,offset:kind==='broad-plan'?0:Math.round((e.clientY-el.getBoundingClientRect().top)/1.2/15)*15};e.dataTransfer.setData('text/plain',`${kind}:${id}`)};el.ondragend=()=>{finalDrag=null;stopScroll()}});document.querySelectorAll('[data-timeline]').forEach(axis=>{const scroller=axis.closest('.timeline-scroll'),minute=y=>Math.max(480,Math.min(1305,Math.round((y-axis.getBoundingClientRect().top)/1.2/15)*15+480)),feedback=axis.querySelector('.drop-feedback');axis.ondragover=e=>{e.preventDefault();if(!finalDrag)return;autoScroll(scroller,e.clientY);const m=minute(e.clientY)-finalDrag.offset;feedback.hidden=false;feedback.style.top=(Math.max(480,m)-480)*1.2+'px';feedback.querySelector('span').textContent=time(Math.max(480,m))};axis.ondragleave=e=>{if(!axis.contains(e.relatedTarget)){feedback.hidden=true;stopScroll()}};axis.ondrop=e=>{e.preventDefault();stopScroll();feedback.hidden=true;if(!finalDrag)return;const drag=finalDrag;finalDrag=null;const m=minute(e.clientY)-drag.offset;if(drag.kind==='task'){const t=taskById(drag.id);t.time=Math.max(480,Math.min(1320-t.duration,m));t.date='2026-10-10';render();notify(`Task ${t.name} 移到 ${time(t.time)}`)}else{const p=plans.find(p=>p.id===drag.id);if(drag.kind==='broad-plan'){const start=Math.min(1260,Math.max(480,m));openPlanEditor(p,start,start+60)}else{const duration=p.end-p.start;p.start=Math.max(480,Math.min(1320-duration,m));p.end=p.start+duration;p.band=bandOf(p.start);render();notify(`当前计划移到 ${planLabel(p)}；早间基准保留`)}}};axis.onpointerdown=e=>{const handle=e.target.closest('[data-resize-plan]');if(handle){e.preventDefault();e.stopPropagation();const p=plans.find(p=>p.id===handle.dataset.resizePlan);finalResize={p,axis,element:handle.closest('[data-plan]'),originalEnd:p.end};axis.setPointerCapture(e.pointerId);return}if(e.target.closest('button')||e.clientX<axis.getBoundingClientRect().left+axis.clientWidth*.51)return;selection={start:minute(e.clientY),end:minute(e.clientY),axis};axis.setPointerCapture(e.pointerId);axis.querySelector('.selection-ghost').classList.remove('hidden')};axis.onpointermove=e=>{if(finalResize&&finalResize.axis===axis){autoScroll(scroller,e.clientY);const p=finalResize.p;p.end=Math.min(1320,Math.max(p.start+15,minute(e.clientY)));finalResize.element.style.height=(p.end-p.start)*1.2+'px';finalResize.element.querySelector('.plan-range').textContent=planLabel(p);return}if(!selection||selection.axis!==axis)return;autoScroll(scroller,e.clientY);selection.end=minute(e.clientY);const ghost=axis.querySelector('.selection-ghost');ghost.style.top=(Math.min(selection.start,selection.end)-480)*1.2+'px';ghost.style.height=Math.max(18,Math.abs(selection.end-selection.start)*1.2)+'px'};axis.onpointerup=e=>{stopScroll();if(finalResize&&finalResize.axis===axis){const p=finalResize.p;finalResize=null;render();notify(`当前计划结束时间改为 ${time(p.end)}；早间基准保留`);return}if(!selection||selection.axis!==axis)return;const start=Math.min(selection.start,selection.end),end=Math.max(selection.start,selection.end);selection=null;axis.querySelector('.selection-ghost').classList.add('hidden');if(end-start>=15)openTaskDialog(null,start,end)};axis.onpointercancel=()=>{stopScroll();if(finalResize){finalResize.p.end=finalResize.originalEnd;finalResize=null;render()}selection=null}})};
bind=()=>{oldBind();document.querySelectorAll('[data-plan],[data-edit-plan]').forEach(el=>el.onclick=()=>openPlanEditor(plans.find(p=>p.id===(el.dataset.plan||el.dataset.editPlan))));document.querySelectorAll('[data-task-more]').forEach(el=>el.onclick=()=>openTaskDialog(taskById(el.dataset.taskMore)));document.querySelectorAll('[data-final-day]').forEach(el=>el.onclick=()=>{selectedDay=+el.dataset.finalDay;render()});document.querySelectorAll('[data-open-final-day]').forEach(el=>el.onclick=()=>{if(+el.dataset.openFinalDay===10){phase=dayStatus(10)==='reviewed'?'evening':'daytime';navigate('today')}else{notify(`示例日期：10 月 ${el.dataset.openFinalDay} 日；完整记录不在本次交互范围`)}});document.querySelectorAll('[data-new-selected]').forEach(el=>el.onclick=()=>{openTaskDialog(null);$('#task-dialog-form').elements.date.value=selectedDate()})};
$('#unchanged-habits').onclick=()=>notify('习惯页面保持现有功能，本次不重新设计');
$('#reset').onclick=()=>{stopScroll();tasks=structuredClone(initialTasks);plans=structuredClone(baseline);selectedDay=10;draft='';messages=[{role:'user',text:'我今天下午想先整理一下安排，晚上留点时间休息。'},{role:'assistant',text:'可以。当前计划既有具体时段，也有尚未定时的午后安排。早间基准会保留，白天可以继续调整。',history:true}];emptyChat=false;scope='all';lastAction='已还原内存示例';render();notify(lastAction)};
$('#previous').hidden=true;$('#next').hidden=true;messages[1].text='当前计划可以同时有具体时间与宽泛时段。白天调整当前计划，早间基准会独立保留。';
render();
